import React, { useState } from 'react';
import { X, Check, Lock, CreditCard, ExternalLink, Loader2 } from 'lucide-react';
import { Logo } from './Logo';
import { User } from '../types';
import { config } from '../config';
import { supabase } from '../services/supabaseClient';

interface OnboardingModalProps {
  onComplete: (user: User) => void;
  onClose: () => void;
  initialStep?: number; // Allow jumping to step 3 if coming back from Stripe
}

export const OnboardingModal: React.FC<OnboardingModalProps> = ({ onComplete, onClose, initialStep = 1 }) => {
  const [step, setStep] = useState(initialStep);
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isRegistering, setIsRegistering] = useState(false);

  // Form State
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const handleNext = () => {
    if (step === 1 && acceptedTerms) setStep(2);
  };

  const handlePay = () => {
    setIsLoading(true);

    // MODIFICACIÓN TEMPORAL: "true || ..." fuerza la simulación aunque haya link real.
    // Esto permite probar el paso 3 sin pagar.
    if (true || config.stripePaymentLink.includes("test_") || config.stripePaymentLink.length < 20) {
        // DEMO MODE / FALLBACK
        console.warn("Modo de pruebas activado: Simulando pago exitoso.");
        setTimeout(() => {
            setIsLoading(false);
            setStep(3);
        }, 1500);
    } else {
        // REAL MODE
        window.location.href = config.stripePaymentLink;
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (name && password) {
      setIsRegistering(true);

      try {
        let userId = undefined;

        // Sync to Supabase if connected
        if (supabase) {
           const { data, error } = await supabase
             .from('cases')
             .insert([{ username: name, password: password, status: 'analyzing' }])
             .select()
             .single();

           if (error) {
             console.error("Supabase Error:", error);
             // If error is duplicate user, we might want to alert, but for MVP we proceed locally or alert
             if (error.code === '23505') {
                 alert("Este nombre de usuario ya existe. Por favor elige otro.");
                 setIsRegistering(false);
                 return;
             }
           } else if (data) {
             userId = data.id;
           }
        }

        onComplete({ id: userId, name, password });
      } catch (err) {
        console.error("Registration error", err);
        // Fallback to local
        onComplete({ name, password });
      }
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-navy-900/90 backdrop-blur-md">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden relative animate-fade-in-up">
        {/* Header */}
        <div className="bg-navy-900 p-6 flex justify-between items-center text-white">
          <div className="flex items-center gap-2">
            <Logo className="w-6 h-6 text-emerald-500" />
            <span className="font-bold">Alta de Caso</span>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white">
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Progress Bar */}
        <div className="h-1 w-full bg-slate-100">
          <div 
            className="h-full bg-emerald-500 transition-all duration-500 ease-out"
            style={{ width: `${(step / 3) * 100}%` }}
          />
        </div>

        {/* Content */}
        <div className="p-8">

          {/* STEP 1: Terms */}
          {step === 1 && (
            <div className="space-y-6">
              <div className="text-center">
                <h2 className="text-2xl font-bold text-navy-900">Antes de empezar</h2>
                <p className="text-slate-500 mt-2">Justino es una herramienta poderosa, pero debemos ser claros.</p>
              </div>

              <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 text-sm text-slate-600 space-y-3">
                <p>1. <strong>Obligación de Medios:</strong> Nos comprometemos a darte la mejor orientación legal basada en la ley vigente.</p>
                <p>2. <strong>No de Resultados:</strong> El éxito de un litigio depende de jueces y terceros.</p>
                <p>3. <strong>IA Supervisada:</strong> Justino es una IA. Revisa siempre los documentos antes de firmar.</p>
              </div>

              <label className="flex items-start gap-3 cursor-pointer group">
                <div className={`mt-1 w-5 h-5 rounded border flex items-center justify-center transition-colors ${acceptedTerms ? 'bg-emerald-500 border-emerald-500' : 'border-slate-300 group-hover:border-emerald-500'}`}>
                  {acceptedTerms && <Check className="w-3 h-3 text-white" />}
                </div>
                <input 
                  type="checkbox" 
                  className="hidden" 
                  checked={acceptedTerms} 
                  onChange={(e) => setAcceptedTerms(e.target.checked)} 
                />
                <span className="text-sm text-slate-700 select-none">He leído y acepto los términos de servicio y responsabilidad.</span>
              </label>

              <button 
                onClick={handleNext}
                disabled={!acceptedTerms}
                className="w-full py-4 bg-navy-900 text-white rounded-xl font-semibold disabled:opacity-50 disabled:cursor-not-allowed hover:bg-navy-800 transition-colors"
              >
                Continuar
              </button>
            </div>
          )}

          {/* STEP 2: Payment */}
          {step === 2 && (
            <div className="space-y-6">
              <div className="text-center">
                <h2 className="text-2xl font-bold text-navy-900">Activa tu Membresía</h2>
                <p className="text-slate-500 mt-2">Pago único por caso.</p>
              </div>

              <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4 flex justify-between items-center">
                <div>
                  <p className="text-emerald-800 font-semibold">Caso Legal Completo</p>
                  <p className="text-emerald-600 text-sm">Acceso ilimitado a Justino</p>
                </div>
                <span className="text-2xl font-bold text-emerald-700">$400</span>
              </div>

              <div className="p-4 bg-slate-50 rounded-xl border border-slate-200 text-sm text-slate-600">
                  <p className="mb-2 font-medium text-navy-900">¿Qué sucederá?</p>
                  <ul className="list-disc pl-4 space-y-1">
                      <li>Serás redirigido a la plataforma segura de Stripe.</li>
                      <li>Podrás pagar con Tarjeta o generar ficha OXXO.</li>
                      <li>Al completar el pago, <strong>regresarás aquí automáticamente</strong> para crear tu cuenta.</li>
                  </ul>
              </div>

              <button 
                onClick={handlePay}
                disabled={isLoading}
                className="w-full py-4 bg-emerald-500 text-white rounded-xl font-bold shadow-lg hover:bg-emerald-600 transition-all flex justify-center items-center gap-2"
              >
                {isLoading ? (
                  <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                    <>
                        <ExternalLink className="w-5 h-5" />
                        Ir a Pagar $400.00 MXN
                    </>
                )}
              </button>
            </div>
          )}

          {/* STEP 3: Account Creation (Post Payment) */}
          {step === 3 && (
            <form onSubmit={handleRegister} className="space-y-6">
              <div className="text-center">
                <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Check className="w-8 h-8 text-emerald-500" />
                </div>
                <h2 className="text-2xl font-bold text-navy-900">¡Pago Recibido!</h2>
                <p className="text-slate-500 mt-2">Crea tus credenciales para acceder a tu caso desde cualquier dispositivo.</p>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-bold text-navy-900 mb-2">Nombre de Usuario</label>
                  <input 
                    type="text" 
                    required
                    placeholder="Ej. JuanPerez88" 
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full p-4 bg-white border-2 border-slate-300 rounded-xl text-navy-900 font-medium placeholder:text-slate-400 focus:border-emerald-500 focus:ring-0 focus:outline-none transition-all shadow-sm"
                  />
                  <p className="text-xs text-slate-400 mt-1 ml-1">Úsalo para entrar en otros dispositivos.</p>
                </div>

                <div>
                  <label className="block text-sm font-bold text-navy-900 mb-2 flex justify-between items-center">
                    Contraseña
                    <button 
                      type="button" 
                      onClick={() => setShowPassword(!showPassword)}
                      className="text-emerald-600 text-xs font-semibold hover:text-emerald-700"
                    >
                      {showPassword ? 'Ocultar' : 'Mostrar'}
                    </button>
                  </label>
                  <div className="relative">
                    <input 
                      type={showPassword ? "text" : "password"} 
                      required
                      placeholder="Crea una clave segura" 
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full p-4 bg-white border-2 border-slate-300 rounded-xl text-navy-900 font-medium placeholder:text-slate-400 focus:border-emerald-500 focus:ring-0 focus:outline-none transition-all shadow-sm"
                    />
                  </div>

                  <div className="mt-3 p-3 bg-blue-50 border border-blue-100 rounded-lg flex gap-3 items-start">
                    <Lock className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
                    <p className="text-xs text-blue-800 font-medium leading-relaxed">
                      Tus datos se encriptarán en la nube. Podrás acceder desde tu celular o computadora usando esta contraseña.
                    </p>
                  </div>
                </div>
              </div>

              <button 
                type="submit"
                disabled={isRegistering}
                className="w-full py-4 bg-navy-900 text-white rounded-xl font-bold text-lg hover:bg-navy-800 transition-colors shadow-lg mt-4 flex justify-center items-center gap-2"
              >
                {isRegistering ? (
                    <>
                        <Loader2 className="w-5 h-5 animate-spin" />
                        Creando Bóveda...
                    </>
                ) : "Crear Cuenta y Acceder"}
              </button>
            </form>
          )}

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MessageSquare, Folder, Map, Bell, Menu, X, BookOpen, Scale, LogOut } from 'lucide-react';
import { User, Message, CaseStatus, DashboardTab, VaultFile } from '../types';
import { ChatInterface } from './ChatInterface';
import { Vault } from './Vault';
import { CaseTimeline } from './CaseTimeline';
import { CaseHistory } from './CaseHistory';
import { LegalFramework } from './LegalFramework';
import { Logo } from './Logo';

interface DashboardProps {
  user: User;
  messages: Message[];
  vaultFiles: VaultFile[]; // Added missing prop
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void; // Updated signature
  onLogout: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  user, 
  messages, 
  vaultFiles, 
  onNewMessage, 
  onAddFile, 
  onLogout 
}) => {
  const [activeTab, setActiveTab] = useState<DashboardTab>('chat');
  const [caseStatus, setCaseStatus] = useState<CaseStatus>('analyzing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Status simulation logic
  useEffect(() => {
    // Check local storage for status first
    const savedStatus = localStorage.getItem('justino_status') as CaseStatus | null;
    if (savedStatus) {
      setCaseStatus(savedStatus);
    } else {
      // Simulation flow only if fresh
      const timer = setTimeout(() => {
        setCaseStatus('in_process');
        localStorage.setItem('justino_status', 'in_process');
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleCaseClosed = () => {
    setCaseStatus('closed');
    localStorage.setItem('justino_status', 'closed');
  };

  const handleDataWipe = () => {
    localStorage.clear();
    window.location.reload();
  };

  const renderStatusBadge = () => {
    switch(caseStatus) {
      case 'analyzing':
        return <span className="flex items-center gap-2 text-xs font-bold text-amber-500 bg-amber-500/10 px-3 py-1 rounded-full"><span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></span> ANALIZANDO</span>;
      case 'in_process':
        return <span className="flex items-center gap-2 text-xs font-bold text-blue-500 bg-blue-500/10 px-3 py-1 rounded-full"><span className="w-2 h-2 rounded-full bg-blue-500"></span> EN PROCESO</span>;
      case 'ready':
        return <span className="flex items-center gap-2 text-xs font-bold text-emerald-500 bg-emerald-500/10 px-3 py-1 rounded-full"><span className="w-2 h-2 rounded-full bg-emerald-500"></span> LISTO</span>;
      case 'closed':
        return <span className="flex items-center gap-2 text-xs font-bold text-slate-500 bg-slate-200 px-3 py-1 rounded-full"><span className="w-2 h-2 rounded-full bg-slate-500"></span> CERRADO</span>;
    }
  };

  const NavItem = ({ id, icon: Icon, label }: { id: DashboardTab; icon: any; label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-colors ${activeTab === id ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'text-slate-400 hover:bg-navy-800 hover:text-white'}`}
    >
      <Icon className="w-5 h-5" />
      <span className="font-medium">{label}</span>
    </button>
  );

  return (
    <div className="h-screen flex flex-col md:flex-row bg-slate-50 overflow-hidden">

      {/* Sidebar (Desktop) / Mobile Menu Overlay */}
      <aside className={`
        fixed inset-0 z-40 bg-navy-900 text-white md:relative md:w-64 md:flex flex-col transition-transform duration-300
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
      `}>
        <div className="p-6 flex justify-between items-center md:block">
          <div className="flex items-center gap-2">
            <Logo className="w-8 h-8 text-emerald-500" />
            <span className="font-bold text-xl tracking-tight">Justino</span>
          </div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="md:hidden text-slate-400">
            <X className="w-6 h-6" />
          </button>
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2">
          <NavItem id="chat" icon={MessageSquare} label="Sala de Chat" />
          <NavItem id="history" icon={BookOpen} label="Historia del Caso" />
          <NavItem id="timeline" icon={Map} label="Mi Ruta Legal" />
          <NavItem id="vault" icon={Folder} label="Mi Bóveda" />
          <div className="pt-4 mt-4 border-t border-navy-800">
            <NavItem id="legal" icon={Scale} label="Marco Legal" />
          </div>
        </nav>

        <div className="p-4 border-t border-navy-800">
          <div className="flex items-center gap-3 mb-4 px-2">
            <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-white font-bold">
              {user.name.charAt(0).toUpperCase()}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-medium text-white truncate">{user.name}</p>
              <p className="text-xs text-slate-400">Plan Estándar</p>
            </div>
          </div>

          <button 
            onClick={onLogout}
            className="w-full flex items-center justify-center gap-2 px-4 py-2 text-xs font-bold uppercase tracking-wider text-red-400 hover:text-white hover:bg-red-500/20 rounded-lg transition-colors border border-red-500/20 hover:border-red-500/50"
          >
            <LogOut className="w-4 h-4" />
            Cerrar Sesión
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-full relative">
        {/* Top Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 z-10 shrink-0">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden text-navy-900">
              <Menu className="w-6 h-6" />
            </button>

            {/* Mobile Branding (Visible only on mobile) */}
            <div className="flex items-center gap-2 md:hidden">
              <Logo className="w-6 h-6 text-emerald-500" />
              <span className="font-bold text-lg tracking-tight text-navy-900">Justino</span>
            </div>

            {/* Desktop Title (Hidden on mobile) */}
            <h2 className="text-lg font-bold text-navy-900 hidden md:block">
              {activeTab === 'chat' && 'Asesoría en Vivo'}
              {activeTab === 'history' && 'Memoria y Cierre'}
              {activeTab === 'vault' && 'Documentos Seguros'}
              {activeTab === 'timeline' && 'Progreso del Caso'}
              {activeTab === 'legal' && 'Bases Legales'}
            </h2>
          </div>

          <div className="flex items-center gap-4">
            {renderStatusBadge()}
            <button className="relative p-2 text-slate-400 hover:text-navy-900 transition-colors">
              <Bell className="w-5 h-5" />
              <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
          </div>
        </header>

        {/* View Switcher */}
        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'chat' && (
            <ChatInterface 
              user={user} 
              messages={messages} 
              onNewMessage={onNewMessage} 
              onAddFile={onAddFile} 
            />
          )}
          {activeTab === 'history' && (
            <CaseHistory 
              messages={messages} 
              caseStatus={caseStatus} 
              onCloseCase={handleCaseClosed}
              onWipeData={handleDataWipe}
            />
          )}
          {activeTab === 'vault' && (
            <Vault files={vaultFiles} />
          )}
          {activeTab === 'timeline' && <CaseTimeline status={caseStatus} />}
          {activeTab === 'legal' && <LegalFramework />}
        </div>
      </main>
    </div>
  );
};

import React, { useState } from 'react';
import { X, Lock, Eye, EyeOff, AlertCircle, ArrowRight, User as UserIcon, Loader2 } from 'lucide-react';
import { Logo } from './Logo';
import { User } from '../types';
import { supabase } from '../services/supabaseClient';

interface LoginModalProps {
  onSuccess: (user: User) => void;
  onClose: () => void;
}

export const LoginModal: React.FC<LoginModalProps> = ({ onSuccess, onClose }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
        let authenticatedUser: User | null = null;

        // 1. Try Supabase Login (Cloud)
        if (supabase) {
            const { data, error: dbError } = await supabase
                .from('cases')
                .select('*')
                .eq('username', username)
                .eq('password', password)
                .single();

            if (data) {
                authenticatedUser = {
                    id: data.id,
                    name: data.username,
                    password: data.password
                };
            } else if (dbError && dbError.code !== 'PGRST116') {
                 // Real DB error (not just "row not found")
                 console.error("DB Login Error:", dbError);
            }
        }

        // 2. Fallback to LocalStorage (Legacy/Offline support)
        if (!authenticatedUser) {
            const storedUserJson = localStorage.getItem('justino_user');
            if (storedUserJson) {
                const storedUser: User = JSON.parse(storedUserJson);
                // Match local storage format which was only password in previous iterations, 
                // but now we expect user to know their username.
                // Simple check: if password matches and (name matches OR we just rely on password for legacy)
                if (storedUser.password === password && storedUser.name === username) {
                    authenticatedUser = storedUser;
                }
            }
        }

        if (authenticatedUser) {
            onSuccess(authenticatedUser);
        } else {
            setError('Usuario o contraseña incorrectos.');
        }

    } catch (err) {
        console.error(err);
        setError('Error de conexión. Intenta nuevamente.');
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-navy-900/90 backdrop-blur-md">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden relative animate-fade-in-up">
        {/* Header */}
        <div className="bg-navy-900 p-6 flex justify-between items-center text-white">
          <div className="flex items-center gap-2">
            <Logo className="w-6 h-6 text-emerald-500" />
            <span className="font-bold">Acceso Seguro</span>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white">
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Content */}
        <div className="p-8">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-navy-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-navy-100">
              <Lock className="w-8 h-8 text-navy-900" />
            </div>
            <h2 className="text-2xl font-bold text-navy-900">Bienvenido de nuevo</h2>
            <p className="text-slate-500 mt-2">Accede a tu caso desde cualquier dispositivo.</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Nombre de Usuario</label>
              <div className="relative">
                <input 
                  type="text" 
                  required
                  autoFocus
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    setError('');
                  }}
                  className="w-full p-4 pr-12 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none transition-shadow text-lg text-navy-900 placeholder:text-slate-400"
                  placeholder="Tu usuario"
                />
                <UserIcon className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Contraseña</label>
              <div className="relative">
                <input 
                  type={showPassword ? "text" : "password"} 
                  required
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    setError('');
                  }}
                  className="w-full p-4 pr-12 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none transition-shadow text-lg text-navy-900 placeholder:text-slate-400"
                  placeholder="••••••••"
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 focus:outline-none"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            {error && (
              <div className="flex items-center gap-2 text-red-600 text-sm bg-red-50 p-3 rounded-lg border border-red-100 animate-pulse-fast">
                <AlertCircle className="w-4 h-4" />
                {error}
              </div>
            )}

            <button 
              type="submit"
              disabled={isLoading}
              className="w-full py-4 bg-navy-900 text-white rounded-xl font-bold shadow-lg hover:bg-navy-800 transition-all flex items-center justify-center gap-2 group disabled:opacity-70"
            >
              {isLoading ? (
                  <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                  <>
                    Abrir Expediente
                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                  </>
              )}
            </button>
          </form>

          <div className="mt-6 text-center">
             <p className="text-xs text-slate-400">
