    setIsLoading(true);

    // PRODUCCIÓN: Lógica de redirección real.
    // Si el link en config.ts contiene "test_" o es muy corto, usamos el modo demo.
    // De lo contrario, redirigimos a la pasarela de pago real.
    if (config.stripePaymentLink.includes("test_") || config.stripePaymentLink.length < 20) {
        // DEMO MODE / FALLBACK (Solo si la config tiene un link de prueba explícito)
        console.warn("Modo de pruebas activado: Simulando pago exitoso.");
        setTimeout(() => {
            setIsLoading(false);
            setStep(3);
