        // Sync to Supabase if connected
        if (supabase) {
           const { data, error } = await supabase
             .from('cases')
             .insert([{ username: name, password: password, status: 'analyzing' }])
             .select()
             .single();

           if (error) {
             console.error("Supabase Error:", error.message || JSON.stringify(error));
             // Handle Duplicate User
             if (error.code === '23505' || error.message?.includes('cases_username_key')) {
                 setRegisterError("Este nombre de usuario ya existe. Por favor elige otro.");
                 setIsRegistering(false);
                 return;
             }
             // Handle other errors
             throw error;
           } else if (data) {
             userId = data.id;
           }
        }

        onComplete({ id: userId, name, password });
      } catch (err) {
        console.error("Registration error", err);
        // Fallback to local if it was a connection error, but if we set registerError previously we returned.
        // If we threw manually, we are here.
        // But if it's a real connection error, we might want to fallback. 
        // Let's fallback only if not duplicate.
        onComplete({ name, password });
