import React, { useState, useEffect, useRef } from 'react';
import { Send, Paperclip, FileText, Download, Scale, X, File, FileSpreadsheet, Image as ImageIcon, Globe, ExternalLink } from 'lucide-react';
import { User, Message, Attachment } from '../types';
import { initializeChat, sendMessageToJustino } from '../services/geminiService';

interface CustomWindow extends Window {
  jspdf: any;
  mammoth: any;
  readXlsxFile: any;
}
declare const window: CustomWindow;

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingText, setLoadingText] = useState('Analizando...');
  const [attachment, setAttachment] = useState<Attachment | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const hasInitialized = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!hasInitialized.current) {
      hasInitialized.current = true;
      initializeChat(user.name, messages);

      if (messages.length === 0) {
        // Intentar obtener ubicación para saludo personalizado
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
            () => {}, // Just trigger permission request
            () => {}
          );
        }

        const welcomeMsg: Message = {
          id: 'welcome',
          text: `Hola ${user.name}, soy Justino. Estás en un espacio seguro.\n\nHe activado mi motor de búsqueda legal en tiempo real. ¿En qué Estado te encuentras y qué problema legal resolvemos hoy?`,
          sender: 'bot',
          timestamp: new Date(),
        };
        onNewMessage(welcomeMsg);
      }
    }
  }, [user.name]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isSending, attachment]);

  useEffect(() => {
    let interval: any;
    if (isSending) {
      const phrases = [
        "Consultando leyes vigentes...",
        "Buscando en el Diario Oficial...",
        "Analizando tu situación...",
        "Verificando jurisprudencia...",
        "Estructurando respuesta legal..."
      ];
      let i = 0;
      setLoadingText(phrases[0]);
      interval = setInterval(() => {
        i = (i + 1) % phrases.length;
        setLoadingText(phrases[i]);
      }, 2500);
    }
    return () => clearInterval(interval);
  }, [isSending]);

  const extractAttribute = (tag: string, attr: string): string => {
    const match = tag.match(new RegExp(`${attr}="([^"]+)"`));
    return match ? match[1] : 'Documento Legal';
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessingFile(true);
    try {
      let content = '';
      let isTextExtracted = false;
      if (file.name.endsWith('.docx') && window.mammoth) {
        const arrayBuffer = await file.arrayBuffer();
        const result = await window.mammoth.extractRawText({ arrayBuffer });
        content = result.value;
        isTextExtracted = true;
      } else if (file.name.endsWith('.xlsx') && window.readXlsxFile) {
        const rows = await window.readXlsxFile(file);
        content = rows.map((row: any[]) => row.join(' | ')).join('\n');
        isTextExtracted = true;
      } else if (file.type === 'text/plain') {
        content = await file.text();
        isTextExtracted = true;
      } else {
        content = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = reject;
          reader.readAsDataURL(file);
        });
        isTextExtracted = false;
      }
      setAttachment({ name: file.name, type: file.type, content: content, isTextExtracted });
    } catch (error) {
      console.error("Error parsing file:", error);
      alert("No pude leer ese archivo.");
    } finally {
      setIsProcessingFile(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentAttachment = attachment;
    const currentInput = input;
    setInput('');
    setAttachment(null);
    setIsSending(true);

    if (currentAttachment) {
        onAddFile(currentAttachment.name, currentAttachment.type, currentAttachment.content, 'uploaded');
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput,
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };

    onNewMessage(userMsg);

    try {
      let apiAttachment = undefined;
      if (currentAttachment) {
          apiAttachment = { ...currentAttachment };
          if (!currentAttachment.isTextExtracted && currentAttachment.content.startsWith('data:')) {
              apiAttachment.content = currentAttachment.content.split(',')[1];
          }
      }

      const { text: responseText, sources } = await sendMessageToJustino(currentInput || "Revisa esto.", apiAttachment);

      const botMsg: Message = {
        id: (Date.now() + 1).toString(),
        text: responseText,
        sender: 'bot',
        timestamp: new Date(),
        sources: sources.length > 0 ? sources : undefined
      };

      onNewMessage(botMsg);

      const docMatch = responseText.match(/<LEGAL_DOC([^>]*)>([\s\S]*?)<\/LEGAL_DOC>/);
      if (docMatch) {
        const [_, attributes, content] = docMatch;
        const title = extractAttribute(attributes, 'title');
        const type = extractAttribute(attributes, 'type');
        onAddFile(title, type, content.trim(), 'generated');
      }
    } catch (error) {
      onNewMessage({ id: 'error', text: "Error de conexión. Intenta de nuevo.", sender: 'bot', timestamp: new Date() });
    } finally {
      setIsSending(false);
    }
  };

  const generatePDF = (title: string, content: string) => {
    if (window.jspdf) {
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF();
      doc.setFillColor(15, 23, 42);
      doc.rect(0, 0, 210, 30, 'F');
      doc.setFontSize(16);
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.text("ASUNTO JURÍDICO", 15, 20);
      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(200, 200, 200);
      doc.text(`FECHA: ${new Date().toLocaleDateString('es-MX').toUpperCase()}`, 160, 20);
      doc.setFontSize(14);
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "bold");
      doc.text(title.toUpperCase(), 15, 50);
      doc.setDrawColor(15, 23, 42);
      doc.setLineWidth(0.5);
      doc.line(15, 53, 195, 53);
      doc.setFontSize(11);
      doc.setFont("times", "normal");
      doc.setTextColor(30, 30, 30);
      const margins = { top: 65, bottom: 20, left: 15, width: 180 };
      const splitText = doc.splitTextToSize(content, margins.width);
      let cursorY = margins.top;
      splitText.forEach((line: string) => {
        if (cursorY > 210 - 20) { doc.addPage(); cursorY = 20; }
        doc.text(line, margins.left, cursorY);
        cursorY += 5;
      });
      doc.save(`${title.replace(/\s+/g, '_')}.pdf`);
    }
  };

  const renderMessageContent = (msg: Message) => {
    const { text, sources } = msg;
    const docMatch = text.match(/<LEGAL_DOC([^>]*)>([\s\S]*?)<\/LEGAL_DOC>/);

    return (
      <div className="space-y-4">
        {docMatch ? (
          <>
            <div className="whitespace-pre-wrap">{text.replace(docMatch[0], '').trim()}</div>
            <div className="bg-white border border-emerald-200 rounded-xl overflow-hidden shadow-lg max-w-sm">
                <div className="bg-emerald-50 p-4 border-b border-emerald-100 flex items-center gap-3">
                    <FileText className="w-6 h-6 text-emerald-600" />
                    <div>
                        <h3 className="font-bold text-navy-900 leading-tight">{extractAttribute(docMatch[1], 'title')}</h3>
                        <p className="text-xs text-emerald-700 uppercase font-semibold">{extractAttribute(docMatch[1], 'type')}</p>
                    </div>
                </div>
                <div className="p-4">
                    <button 
                        onClick={() => generatePDF(extractAttribute(docMatch[1], 'title'), docMatch[2].trim())}
                        className="w-full py-2 bg-navy-900 text-white rounded-lg font-bold flex items-center justify-center gap-2"
                    >
                        <Download className="w-4 h-4" /> Descargar PDF
                    </button>
                </div>
            </div>
          </>
        ) : (
          <div className="whitespace-pre-wrap">{text}</div>
        )}

        {/* Grounding Sources UI */}
