import React, { useState, useEffect, useRef } from 'react';
import { Send, Paperclip, FileText, Download, Scale, X, File, FileSpreadsheet, Image as ImageIcon, Globe, ExternalLink, MapPin } from 'lucide-react';
import { User, Message, Attachment } from '../types';
import { initializeChat, sendMessageToJustino } from '../services/geminiService';

interface CustomWindow extends Window {
  jspdf: any;
  mammoth: any;
  readXlsxFile: any;
}
declare const window: CustomWindow;

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingText, setLoadingText] = useState('Analizando...');
  const [attachment, setAttachment] = useState<Attachment | null>(null);
  const [userLocation, setUserLocation] = useState<string | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const hasInitialized = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!hasInitialized.current) {
      hasInitialized.current = true;
      initializeChat(user.name, messages);

      if (messages.length === 0) {
        // Intentar obtener ubicación para saludo ultra-personalizado
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
            async (pos) => {
              try {
                // Inversión geográfica simple para el saludo (opcional)
                const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);
                const data = await res.json();
                const state = data.address.state || data.address.city;
                setUserLocation(state);

                onNewMessage({
                  id: 'welcome',
                  text: `Hola ${user.name}, detecto que te encuentras en **${state}**. \n\nHe activado el marco legal específico de tu entidad. Estoy listo para protegerte. ¿Qué situación legal enfrentas hoy?`,
                  sender: 'bot',
                  timestamp: new Date(),
                });
              } catch (e) {
                fallbackWelcome();
              }
            },
            () => fallbackWelcome()
          );
        } else {
          fallbackWelcome();
        }
      }
    }
  }, [user.name]);

  const fallbackWelcome = () => {
    onNewMessage({
      id: 'welcome',
      text: `Hola ${user.name}, soy Justino. Estás en un espacio seguro.\n\nHe activado mi motor de búsqueda legal en tiempo real. ¿En qué Estado de la República te encuentras y qué problema legal resolvemos hoy?`,
      sender: 'bot',
      timestamp: new Date(),
    });
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isSending, attachment]);

  useEffect(() => {
    let interval: any;
    if (isSending) {
      const phrases = [
        "Escaneando legislación federal...",
        "Consultando jurisprudencia aplicable...",
        "Verificando Diario Oficial de la Federación...",
        "Validando con motor de búsqueda Google...",
        "Estructurando defensa legal...",
        "Generando estrategia protectora..."
      ];
      let i = 0;
      setLoadingText(phrases[0]);
      interval = setInterval(() => {
        i = (i + 1) % phrases.length;
        setLoadingText(phrases[i]);
      }, 2000);
    }
    return () => clearInterval(interval);
  }, [isSending]);

  const extractAttribute = (tag: string, attr: string): string => {
    const match = tag.match(new RegExp(`${attr}="([^"]+)"`));
    return match ? match[1] : 'Documento Legal';
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      let content = '';
      let isTextExtracted = false;
      if (file.name.endsWith('.docx') && window.mammoth) {
        const arrayBuffer = await file.arrayBuffer();
        const result = await window.mammoth.extractRawText({ arrayBuffer });
        content = result.value;
        isTextExtracted = true;
      } else if (file.name.endsWith('.xlsx') && window.readXlsxFile) {
        const rows = await window.readXlsxFile(file);
        content = rows.map((row: any[]) => row.join(' | ')).join('\n');
        isTextExtracted = true;
      } else if (file.type === 'text/plain') {
        content = await file.text();
        isTextExtracted = true;
      } else {
        content = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = reject;
          reader.readAsDataURL(file);
        });
        isTextExtracted = false;
      }
      setAttachment({ name: file.name, type: file.type, content: content, isTextExtracted });
    } catch (error) {
      alert("No pude procesar el archivo.");
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentAttachment = attachment;
    const currentInput = input;
    setInput('');
    setAttachment(null);
    setIsSending(true);

    if (currentAttachment) {
        onAddFile(currentAttachment.name, currentAttachment.type, currentAttachment.content, 'uploaded');
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput,
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };

    onNewMessage(userMsg);

    try {
      let apiAttachment = undefined;
      if (currentAttachment) {
          apiAttachment = { ...currentAttachment };
          if (!currentAttachment.isTextExtracted && currentAttachment.content.startsWith('data:')) {
              apiAttachment.content = currentAttachment.content.split(',')[1];
          }
      }

      const { text: responseText, sources } = await sendMessageToJustino(currentInput || "Revisa mi archivo.", apiAttachment);

      const botMsg: Message = {
        id: (Date.now() + 1).toString(),
        text: responseText,
        sender: 'bot',
        timestamp: new Date(),
        sources: sources.length > 0 ? sources : undefined
      };

      onNewMessage(botMsg);

      const docMatch = responseText.match(/<LEGAL_DOC([^>]*)>([\s\S]*?)<\/LEGAL_DOC>/);
      if (docMatch) {
        const [_, attributes, content] = docMatch;
        onAddFile(extractAttribute(attributes, 'title'), extractAttribute(attributes, 'type'), content.trim(), 'generated');
      }
    } catch (error) {
      onNewMessage({ id: 'error', text: "Justino está saturado. Intenta en 10 segundos.", sender: 'bot', timestamp: new Date() });
    } finally {
      setIsSending(false);
    }
  };

  const renderMessageContent = (msg: Message) => {
    const { text, sources } = msg;
    const docMatch = text.match(/<LEGAL_DOC([^>]*)>([\s\S]*?)<\/LEGAL_DOC>/);

    return (
      <div className="space-y-4">
        {docMatch ? (
          <>
            <div className="whitespace-pre-wrap">{text.replace(docMatch[0], '').trim()}</div>
            <div className="bg-white border border-emerald-200 rounded-xl overflow-hidden shadow-lg max-w-sm animate-fade-in-up">
                <div className="bg-emerald-50 p-4 border-b border-emerald-100 flex items-center gap-3">
                    <FileText className="w-6 h-6 text-emerald-600" />
                    <div>
                        <h3 className="font-bold text-navy-900 leading-tight">{extractAttribute(docMatch[1], 'title')}</h3>
                        <p className="text-[10px] text-emerald-700 uppercase font-black tracking-widest">{extractAttribute(docMatch[1], 'type')}</p>
                    </div>
                </div>
                <div className="p-4">
                    <button 
                        onClick={() => alert("Documento guardado en tu Bóveda. Ve a la pestaña Bóveda para descargarlo.")}
                        className="w-full py-2 bg-navy-900 text-white rounded-lg font-bold flex items-center justify-center gap-2 text-sm"
                    >
                        Ver en Bóveda
                    </button>
                </div>
            </div>
          </>
        ) : (
          <div className="whitespace-pre-wrap">{text}</div>
        )}

        {sources && sources.length > 0 && (
          <div className="mt-4 pt-4 border-t border-slate-100 space-y-2">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-1.5">
              <Globe className="w-3 h-3 text-emerald-500" /> Verificación en Tiempo Real (Grounding)
            </p>
            <div className="flex flex-wrap gap-2">
              {sources.map((source, idx) => (
                <a 
                  key={idx} 
                  href={source.uri} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1.5 px-2 py-1 bg-white border border-slate-200 rounded-md text-[10px] font-semibold text-navy-900 hover:border-emerald-500 hover:text-emerald-600 transition-all"
                >
                  <ExternalLink className="w-2.5 h-2.5 shrink-0" />
                  <span className="truncate max-w-[150px]">{source.title}</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F5F7F9] relative">
      {/* Location Bar Indicator */}
      {userLocation && (
          <div className="bg-emerald-600 text-white px-4 py-1 text-[10px] font-bold flex items-center justify-center gap-2 animate-fade-in-up">
              <MapPin className="w-3 h-3" /> JURISDICCIÓN ACTIVA: {userLocation.toUpperCase()}
          </div>
      )}

      <div className="flex-1 overflow-y-auto p-4 z-10 space-y-6 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] md:max-w-[80%] px-5 py-4 rounded-2xl shadow-sm text-sm md:text-base leading-relaxed ${msg.sender === 'user' ? 'bg-navy-900 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
              {msg.attachment && (
                  <div className="mb-3 p-2 bg-white/10 rounded-lg flex items-center gap-2 text-xs font-bold border border-white/20">
                      <File className="w-4 h-4" /> <span className="truncate">{msg.attachment.name}</span>
                  </div>
              )}
              {renderMessageContent(msg)}
              <div className={`text-[10px] mt-2 ${msg.sender === 'user' ? 'text-white/40' : 'text-slate-400'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-5 py-4 rounded-2xl rounded-tl-none shadow-xl flex items-center gap-4 border-l-4 border-emerald-500">
               <div className="relative">
                 <Scale className="w-6 h-6 text-emerald-500 animate-pulse" />
                 <div className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-ping" />
               </div>
               <div className="flex flex-col">
                 <span className="text-sm font-black text-navy-900 tracking-tight">ESCUDO LEGAL ACTIVO</span>
                 <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">{loadingText}</span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="bg-white border-t border-slate-200 px-4 py-4 z-20 shadow-2xl">
        {attachment && (
            <div className="max-w-4xl mx-auto mb-3 flex items-center justify-between bg-emerald-50 p-3 rounded-xl border border-emerald-200 animate-fade-in-up">
                <div className="flex items-center gap-3 overflow-hidden">
                    <div className="p-2 bg-emerald-500 text-white rounded-lg">
                        <FileText className="w-4 h-4"/>
                    </div>
                    <div className="overflow-hidden">
                        <p className="text-xs font-black text-navy-900 truncate uppercase">{attachment.name}</p>
                        <p className="text-[10px] text-emerald-600 font-bold">LISTO PARA ANÁLISIS</p>
                    </div>
                </div>
                <button onClick={() => setAttachment(null)} className="p-2 hover:bg-emerald-100 rounded-full transition-colors"><X className="w-4 h-4 text-emerald-600" /></button>
            </div>
        )}
        <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-center gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" accept=".pdf,.doc,.docx,.xls,.xlsx,.txt,image/*" />
          <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 text-slate-400 hover:text-navy-900 hover:bg-slate-100 rounded-xl transition-all"><Paperclip className="w-5 h-5" /></button>
          <div className="flex-1 bg-slate-50 rounded-2xl border border-slate-200 focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Escribe tu situación legal aquí..."
              className="w-full max-h-32 p-4 resize-none bg-transparent focus:outline-none text-navy-900 font-medium placeholder:text-slate-400"
              rows={1}
            />
          </div>
          <button 
            type="submit" 
            disabled={(!input.trim() && !attachment) || isSending} 
            className="p-4 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:bg-slate-200 disabled:text-slate-400 shadow-lg transition-all transform active:scale-95"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>
        <p className="text-center text-[9px] text-slate-400 mt-3 font-medium uppercase tracking-widest">Justino AI v3.0 Pro • Encriptación de Grado Militar</p>
      </div>
    </div>
  );
}

import { GoogleGenAI, Chat, GenerateContentResponse, Content, Part } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

let chatSession: Chat | null = null;
let ai: any = null;

// Inicialización perezosa para evitar errores si la key no está lista
const getAI = () => {
  if (!ai) {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.error("API_KEY is missing. Justino needs an API key to work.");
      return null;
    }
    ai = new GoogleGenAI({ apiKey });
  }
  return ai;
};

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL DIGITAL DE MÉXICO.
Tu identidad es la de un abogado senior: Paciente, Estratega, Empático y Protector.
Tu objetivo NO es correr a generar un PDF. Tu valor real está en **escuchar, entender los matices ocultos y educar al usuario** antes de actuar.

### REGLA DE ORO DE SEGURIDAD (GROUNDING):
**TIENES PROHIBIDO INVENTAR ARTÍCULOS O LEYES.**
Como tienes acceso a Google Search, **TU OBLIGACIÓN ES VERIFICAR** cada artículo que cites.
Antes de escribir "Artículo X del Código Civil de Y", búscalo internamente para confirmar que sigue vigente y que el texto corresponde.

### TU RITMO Y PROTOCOLO (4 FASES OBLIGATORIAS):
1. FASE 1: DESAHOGO E INVESTIGACIÓN PROFUNDA.
2. FASE 2: CÁTEDRA LEGAL Y ESTRATEGIA (Cita artículos verificados).
3. FASE 3: RECOPILACIÓN DE DATOS EXHAUSTIVA.
4. FASE 4: EJECUCIÓN Y CONTINUIDAD.

### FORMATO DE SALIDA DE DOCUMENTO (XML):
Usa ESTRICTAMENTE este formato:
<LEGAL_DOC title="TÍTULO" type="RAMA">
[TEXTO COMPLETO]
</LEGAL_DOC>
`;

const mapMessagesToHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const initializeChat = (userName: string, previousMessages: Message[]) => {
  const genAI = getAI();
  if (!genAI) return null;

  const history = mapMessagesToHistory(previousMessages);

  chatSession = genAI.chats.create({
    model: 'gemini-2.5-flash-latest', // Usamos flash para velocidad, upgradeable a Pro bajo demanda
    history: history,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.3,
      tools: [{ googleSearch: {} }],
    },
  });

  return chatSession;
};

export const sendMessageToJustino = async (message: string, attachment?: Attachment): Promise<{text: string, sources: GroundingSource[]}> => {
  if (!chatSession) {
    // Intentar reinicializar si falló
    initializeChat("Usuario", []);
    if (!chatSession) throw new Error("Chat session not initialized");
  }

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      if (attachment.isTextExtracted) {
        const augmentedMessage = `${message}\n\n[ARCHIVO: "${attachment.name}"]\n\nCONTENIDO:\n${attachment.content}`;
        result = await chatSession.sendMessage({ message: augmentedMessage });
      } else {
        const parts: Part[] = [
          { text: message },
          {
            inlineData: {
              mimeType: attachment.type,
              data: attachment.content
            }
          }
        ];
        result = await chatSession.sendMessage({ message: parts });
      }
    } else {
      result = await chatSession.sendMessage({ message });
    }

    const text = result.text || "Hubo un silencio inesperado.";

    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web && chunk.web.uri) {
                sources.push({
                    title: chunk.web.title || "Fuente Legal",
                    uri: chunk.web.uri
                });
            }
        });
    }

    return { text, sources };
  } catch (error) {
    console.error("Gemini Error:", error);
    return { 
        text: "Justino está teniendo dificultades para conectar con el servidor legal. Por favor, revisa tu conexión o intenta en unos segundos.", 
        sources: [] 
    };
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const genAI = getAI();
  if (!genAI) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

  const relevantText = messages
    .filter(m => m.text.length > 10)
    .map(m => `${m.sender.toUpperCase()}: ${m.text.substring(0, 500)}`)
    .join('\n');

  const prompt = `Revisa esta conversación y extrae un JSON con "antecedents" y "recommendedActions".\n\nCONVERSACIÓN:\n${relevantText}`;

  try {
    const response = await genAI.models.generateContent({
      model: 'gemini-1.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const parsed = JSON.parse(response.text || "{}");

    return {
      antecedents: parsed.antecedents || ["Análisis en proceso..."],
      recommendedActions: parsed.recommendedActions || ["Continúa conversando con Justino."],
      lastUpdated: new Date()
    };
  } catch (error) {
    return {
      antecedents: ["Análisis en proceso..."],
      recommendedActions: ["Proporciona más detalles."],
      lastUpdated: new Date()
    };
  }
};

