let chatSession: Chat | null = null;
let aiInstance: GoogleGenAI | null = null;

// Inicialización perezosa siguiendo las directrices del SDK
const getAI = () => {
  if (!aiInstance) {
    const apiKey = process.env.API_KEY;
    if (!apiKey || apiKey === "undefined" || apiKey.length < 5) {
      console.error("CRÍTICO: No se detectó API_KEY. Justino no puede procesar consultas.");
      return null;
    }
    aiInstance = new GoogleGenAI({ apiKey });
  }
  return aiInstance;
