    throw new Error("NO_API_KEY");
  }

  if (!chatSession) {
    initializeChat("Usuario", []);
    if (!chatSession) throw new Error("NO_SESSION");
  }

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      if (attachment.isTextExtracted) {
        const augmentedMessage = `${message}\n\n[ARCHIVO: "${attachment.name}"]\n\nCONTENIDO:\n${attachment.content}`;
        result = await chatSession.sendMessage({ message: augmentedMessage });
      } else {
        const parts: Part[] = [
          { text: message || "Analiza este archivo." },
          {
            inlineData: {
              mimeType: attachment.type,
              data: attachment.content
            }
          }
        ];
        result = await chatSession.sendMessage({ message: parts });
      }
    } else {
      result = await chatSession.sendMessage({ message });
    }

    const text = result.text || "Justino recibió una respuesta vacía del sistema legal.";

    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web && chunk.web.uri) {
                sources.push({
                    title: chunk.web.title || "Fuente Legal",
                    uri: chunk.web.uri
                });
            }
        });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Gemini Error:", error);
    if (error.message?.includes("404") || error.message?.includes("not found")) {
      throw new Error("MODEL_NOT_FOUND");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const ai = getAIInstance();
  if (!ai) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

  const relevantText = messages
    .filter(m => m.text.length > 5)
    .map(m => `${m.sender.toUpperCase()}: ${m.text.substring(0, 300)}`)
    .join('\n');

  const prompt = `Resume este caso legal en JSON: {"antecedents": [], "recommendedActions": []}. CONVERSACIÓN:\n${relevantText}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: ["Análisis en curso..."], recommendedActions: ["Continúa la asesoría."], lastUpdated: new Date() };
  }
};

