  jspdf: any;
  mammoth: any;
  readXlsxFile: any;
  aistudio: any;
}
declare const window: CustomWindow;

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingText, setLoadingText] = useState('Analizando...');
  const [attachment, setAttachment] = useState<Attachment | null>(null);
  const [userLocation, setUserLocation] = useState<string | null>(null);
  const [isApiKeyMissing, setIsApiKeyMissing] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const hasInitialized = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Verificar si la llave está disponible
  useEffect(() => {
    const checkKey = () => {
      const key = process.env.API_KEY;
      setIsApiKeyMissing(!key || key === "undefined" || key.length < 5);
    };
    checkKey();
    const interval = setInterval(checkKey, 2000); // Check periodic for dynamic injection
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!hasInitialized.current) {
      hasInitialized.current = true;
      initializeChat(user.name, messages);

      if (messages.length === 0) {
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
            async (pos) => {
              try {
                const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);
                const data = await res.json();
                const state = data.address.state || data.address.city || "México";
                setUserLocation(state);
                onNewMessage({
                  id: 'welcome',
                  text: `Hola ${user.name}, detecto que te encuentras en **${state}**. He activado el marco legal específico de tu entidad. Estoy listo para protegerte.`,
                  sender: 'bot',
                  timestamp: new Date(),
                });
              } catch (e) { fallbackWelcome(); }
            },
            () => fallbackWelcome()
          );
        } else { fallbackWelcome(); }
      }
    }
  }, [user.name]);

  const fallbackWelcome = () => {
    onNewMessage({
      id: 'welcome',
      text: `Hola ${user.name}, soy Justino. He activado mi motor de búsqueda legal. ¿En qué Estado te encuentras y qué problema resolvemos hoy?`,
      sender: 'bot',
      timestamp: new Date(),
    });
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isSending, attachment, isApiKeyMissing]);

  const handleOpenKeySelector = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
    } else {
      alert("Por favor, asegúrate de tener una API Key configurada en tu entorno de desarrollo.");
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending || isApiKeyMissing) return;

    const currentAttachment = attachment;
    const currentInput = input;
    setInput('');
    setAttachment(null);
    setIsSending(true);

    if (currentAttachment) onAddFile(currentAttachment.name, currentAttachment.type, currentAttachment.content, 'uploaded');

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput || (currentAttachment ? `Analiza: ${currentAttachment.name}` : ""),
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };
    onNewMessage(userMsg);

    try {
      let apiAttachment = undefined;
      if (currentAttachment) {
          apiAttachment = { ...currentAttachment };
          if (!currentAttachment.isTextExtracted && currentAttachment.content.startsWith('data:')) {
              apiAttachment.content = currentAttachment.content.split(',')[1];
          }
      }

      const response = await sendMessageToJustino(currentInput, apiAttachment);
      onNewMessage({
        id: (Date.now() + 1).toString(),
        text: response.text,
        sender: 'bot',
        timestamp: new Date(),
        sources: response.sources.length > 0 ? response.sources : undefined
      });
    } catch (error: any) {
      let errorText = "Justino está teniendo dificultades. Intenta de nuevo.";
      if (error.message === "NO_API_KEY") {
        setIsApiKeyMissing(true);
        errorText = "Se ha perdido la conexión con el motor legal. Por favor, actívalo arriba.";
      }
      onNewMessage({ id: 'error', text: errorText, sender: 'bot', timestamp: new Date() });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F5F7F9] relative">
      {/* Barra de Jurisdicción o Alerta de Llave */}
      {isApiKeyMissing ? (
        <div className="bg-amber-500 text-white px-4 py-3 text-xs font-bold flex items-center justify-between gap-2 animate-bounce-subtle z-30 shadow-lg">
           <div className="flex items-center gap-2">
              <ShieldAlert className="w-4 h-4" />
              <span>JUSTINO REQUIERE ACTIVACIÓN (FALTA LLAVE DE IA)</span>
           </div>
           <button 
              onClick={handleOpenKeySelector}
              className="bg-white text-amber-600 px-3 py-1 rounded-full flex items-center gap-1 hover:bg-navy-900 hover:text-white transition-all shadow-sm"
           >
              <Key className="w-3 h-3" /> Activar Ahora
           </button>
        </div>
      ) : userLocation && (
        <div className="bg-emerald-600 text-white px-4 py-1 text-[10px] font-bold flex items-center justify-center gap-2">
            <MapPin className="w-3 h-3" /> JURISDICCIÓN ACTIVA: {userLocation.toUpperCase()}
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-4 z-10 space-y-6 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] md:max-w-[80%] px-5 py-4 rounded-2xl shadow-sm text-sm leading-relaxed ${msg.sender === 'user' ? 'bg-navy-900 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
              {msg.attachment && (
                  <div className="mb-3 p-2 bg-white/10 rounded-lg flex items-center gap-2 text-xs font-bold border border-white/20">
                      <File className="w-4 h-4" /> <span className="truncate">{msg.attachment.name}</span>
                  </div>
              )}
              <div className="space-y-4">
                <div className="whitespace-pre-wrap">{msg.text}</div>
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-slate-100 space-y-2">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-1.5">
                      <Globe className="w-3 h-3 text-emerald-500" /> Verificación Legal Activa
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((s, i) => (
                        <a key={i} href={s.uri} target="_blank" rel="noopener" className="inline-flex items-center gap-1 px-2 py-1 bg-white border border-slate-200 rounded text-[10px] font-semibold text-navy-900 hover:text-emerald-600 transition-all">
                          <ExternalLink className="w-2.5 h-2.5" /> <span className="truncate max-w-[150px]">{s.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {/* Empty State / Key Missing Prompt */}
        {isApiKeyMissing && messages.length < 5 && (
            <div className="flex flex-col items-center justify-center py-20 text-center animate-fade-in-up">
                <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center mb-6">
                    <Zap className="w-10 h-10 text-amber-500 animate-pulse" />
                </div>
                <h3 className="text-xl font-bold text-navy-900">Motor Legal Desactivado</h3>
                <p className="text-slate-500 max-w-xs mt-2 text-sm">Justino necesita una conexión segura a la IA para poder analizar tu caso legal.</p>
                <button 
                    onClick={handleOpenKeySelector}
                    className="mt-6 px-8 py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-xl hover:bg-emerald-600 transition-all flex items-center gap-2"
                >
                    <Key className="w-5 h-5" /> Vincular Mi Cuenta de IA
                </button>
                <p className="mt-4 text-[10px] text-slate-400 max-w-[200px]">Esto habilitará a Justino para usar los modelos de Gemini 3 Flash y búsqueda en Google.</p>
            </div>
        )}

        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-5 py-4 rounded-2xl rounded-tl-none shadow-xl flex items-center gap-4 border-l-4 border-emerald-500">
               <Scale className="w-6 h-6 text-emerald-500 animate-pulse" />
               <div className="flex flex-col">
                 <span className="text-sm font-black text-navy-900">ESCUDO LEGAL ACTIVO</span>
                 <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">PROCESANDO...</span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="bg-white border-t border-slate-200 px-4 py-4 z-20 shadow-2xl">
        <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-center gap-3">
          <input type="file" ref={fileInputRef} onChange={() => {}} className="hidden" />
          <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 text-slate-400 hover:text-navy-900 rounded-xl transition-all"><Paperclip className="w-5 h-5" /></button>
          <div className={`flex-1 rounded-2xl border transition-all shadow-inner ${isApiKeyMissing ? 'bg-slate-100 border-slate-200 cursor-not-allowed' : 'bg-slate-50 border-slate-200 focus-within:border-emerald-500 focus-within:bg-white'}`}>
            <textarea
              value={input}
              disabled={isApiKeyMissing}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder={isApiKeyMissing ? "Justino requiere activación..." : "Escribe tu situación legal aquí..."}
              className="w-full max-h-32 p-4 resize-none bg-transparent focus:outline-none text-navy-900 font-medium disabled:opacity-50"
              rows={1}
            />
          </div>
          <button 
            type="submit" 
            disabled={(!input.trim() && !attachment) || isSending || isApiKeyMissing} 
            className="p-4 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:bg-slate-200 disabled:text-slate-400 shadow-lg transition-all"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>
      </div>
    </div>
  );
}

