import { GoogleGenAI, Chat, GenerateContentResponse, Content, Part } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

let chatSession: Chat | null = null;

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  // Si no hay API_KEY, el SDK fallará naturalmente al intentar la llamada, 
  // lo cual manejaremos en el try/catch de sendMessage.
  return new GoogleGenAI({ apiKey: apiKey || "" });
};

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL DIGITAL DE MÉXICO.
Identidad: Abogado senior, empático y protector.
Misión: Escuchar, analizar matices legales y generar documentos basados en leyes reales.

REGLAS CRÍTICAS:
1. Cita artículos vigentes de México (Constitución, Códigos Civiles/Penales Estatales).
2. Usa Google Search para verificar que la ley citada no haya sido derogada.
3. Si generas un documento, usa el formato <LEGAL_DOC title="..." type="...">...</LEGAL_DOC>.
`;

const mapMessagesToHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const initializeChat = (userName: string, previousMessages: Message[]) => {
  const ai = getAIInstance();
  const history = mapMessagesToHistory(previousMessages);

  chatSession = ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.3,
      tools: [{ googleSearch: {} }],
    },
    history: history,
  });

  return chatSession;
};

export const sendMessageToJustino = async (message: string, attachment?: Attachment): Promise<{text: string, sources: GroundingSource[]}> => {
  if (!chatSession) {
    initializeChat("Usuario", []);
    if (!chatSession) throw new Error("No se pudo conectar con el motor legal.");
  }

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      if (attachment.isTextExtracted) {
        const augmentedMessage = `${message}\n\n[ARCHIVO: "${attachment.name}"]\n\nCONTENIDO:\n${attachment.content}`;
        result = await chatSession.sendMessage({ message: augmentedMessage });
      } else {
        const parts: Part[] = [
          { text: message || "Analiza este archivo legal." },
          {
            inlineData: {
              mimeType: attachment.type,
              data: attachment.content
            }
          }
        ];
        result = await chatSession.sendMessage({ message: parts });
      }
    } else {
      result = await chatSession.sendMessage({ message });
    }

    const text = result.text || "Justino está procesando la información...";

    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web && chunk.web.uri) {
                sources.push({
                    title: chunk.web.title || "Fuente Legal Verificada",
                    uri: chunk.web.uri
                });
            }
        });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Justino Engine Error:", error);
    // Error genérico para el usuario, sin detalles técnicos de API Keys
    return { 
      text: "Justino está experimentando una alta demanda de consultas legales en este momento. Por favor, intenta enviar tu mensaje nuevamente en unos segundos.", 
      sources: [] 
    };
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const ai = getAIInstance();
  const relevantText = messages
    .filter(m => m.text.length > 5)
    .map(m => `${m.sender.toUpperCase()}: ${m.text.substring(0, 200)}`)
    .join('\n');

  const prompt = `Analiza y resume en JSON: {"antecedents": [], "recommendedActions": []}. Texto:\n${relevantText}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || ["Analizando hechos del caso..."],
      recommendedActions: parsed.recommendedActions || ["Justino está definiendo la mejor estrategia legal."],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Send, Paperclip, FileText, Scale, X, File, Globe, ExternalLink, MapPin } from 'lucide-react';
import { User, Message, Attachment } from '../types';
import { initializeChat, sendMessageToJustino } from '../services/geminiService';

interface CustomWindow extends Window {
  jspdf: any;
  mammoth: any;
  readXlsxFile: any;
}
declare const window: CustomWindow;

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingText, setLoadingText] = useState('Analizando...');
  const [attachment, setAttachment] = useState<Attachment | null>(null);
  const [userLocation, setUserLocation] = useState<string | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const hasInitialized = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!hasInitialized.current) {
      hasInitialized.current = true;
      initializeChat(user.name, messages);

      if (messages.length === 0) {
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
            async (pos) => {
              try {
                const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);
                const data = await res.json();
                const state = data.address.state || data.address.city || "México";
                setUserLocation(state);
                onNewMessage({
                  id: 'welcome',
                  text: `Hola ${user.name}, detecto que te encuentras en **${state}**. He activado el marco legal de tu entidad. Estoy listo para asesorarte.`,
                  sender: 'bot',
                  timestamp: new Date(),
                });
              } catch (e) { fallbackWelcome(); }
            },
            () => fallbackWelcome()
          );
        } else { fallbackWelcome(); }
      }
    }
  }, [user.name]);

  const fallbackWelcome = () => {
    onNewMessage({
      id: 'welcome',
      text: `Hola ${user.name}, soy Justino. He activado mi motor de búsqueda legal en tiempo real. ¿Qué situación enfrentamos hoy?`,
      sender: 'bot',
      timestamp: new Date(),
    });
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isSending, attachment]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentAttachment = attachment;
    const currentInput = input;
    setInput('');
    setAttachment(null);
    setIsSending(true);

    if (currentAttachment) onAddFile(currentAttachment.name, currentAttachment.type, currentAttachment.content, 'uploaded');

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput || (currentAttachment ? `Análisis de: ${currentAttachment.name}` : ""),
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };
    onNewMessage(userMsg);

    try {
      const response = await sendMessageToJustino(currentInput, currentAttachment || undefined);
      onNewMessage({
        id: (Date.now() + 1).toString(),
        text: response.text,
        sender: 'bot',
        timestamp: new Date(),
        sources: response.sources.length > 0 ? response.sources : undefined
      });
    } catch (error) {
      onNewMessage({ 
        id: 'error', 
        text: "Justino tuvo un problema de conexión. Por favor, reintenta tu mensaje.", 
        sender: 'bot', 
        timestamp: new Date() 
      });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F5F7F9] relative">
      {userLocation && (
        <div className="bg-emerald-600 text-white px-4 py-1 text-[10px] font-bold flex items-center justify-center gap-2 z-20">
            <MapPin className="w-3 h-3" /> JURISDICCIÓN ACTIVA: {userLocation.toUpperCase()}
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-4 z-10 space-y-6 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] md:max-w-[80%] px-5 py-4 rounded-2xl shadow-sm text-sm leading-relaxed ${msg.sender === 'user' ? 'bg-navy-900 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
              <div className="space-y-4">
                <div className="whitespace-pre-wrap">{msg.text}</div>
                {msg.sources && (
                  <div className="mt-4 pt-4 border-t border-slate-100 flex flex-wrap gap-2">
                    {msg.sources.map((s, i) => (
                      <a key={i} href={s.uri} target="_blank" rel="noopener" className="inline-flex items-center gap-1 px-2 py-1 bg-white border border-slate-200 rounded text-[10px] font-semibold text-navy-900 hover:text-emerald-600">
                        <ExternalLink className="w-2.5 h-2.5" /> <span className="truncate max-w-[120px]">{s.title}</span>
                      </a>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-5 py-4 rounded-2xl rounded-tl-none shadow-xl flex items-center gap-4 border-l-4 border-emerald-500">
               <Scale className="w-6 h-6 text-emerald-500 animate-pulse" />
               <div className="flex flex-col">
                 <span className="text-sm font-black text-navy-900">ESCUDO LEGAL ACTIVO</span>
                 <span className="text-[10px] text-emerald-600 font-bold tracking-widest uppercase">Consultando...</span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="bg-white border-t border-slate-200 px-4 py-4 z-20 shadow-2xl">
        <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-center gap-3">
          <input type="file" ref={fileInputRef} className="hidden" />
          <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 text-slate-400 hover:text-navy-900 transition-all"><Paperclip className="w-5 h-5" /></button>
          <div className="flex-1 bg-slate-50 rounded-2xl border border-slate-200 focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Explica tu situación legal..."
              className="w-full max-h-32 p-4 resize-none bg-transparent focus:outline-none text-navy-900 font-medium"
              rows={1}
            />
          </div>
          <button 
            type="submit" 
            disabled={(!input.trim() && !attachment) || isSending} 
            className="p-4 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:bg-slate-200 transition-all shadow-lg"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>
      </div>
    </div>
  );
}

import { GoogleGenAI, Chat, GenerateContentResponse, Content, Part } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

// Instrucción maestra para Justino
const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL DIGITAL LÍDER EN MÉXICO.
Tu tono es profesional, protector, experto y altamente estratégico.

PROTOCOLO DE OPERACIÓN:
1. Veracidad: Cita leyes mexicanas reales (Constitución, Códigos Civiles, Penales, Laborales).
2. Grounding: Usa la herramienta de Google Search para confirmar que los artículos citados están vigentes a la fecha de hoy.
3. Entorno: Si el usuario menciona un Estado, adapta la asesoría a la legislación local de esa entidad.
4. Formato: Genera documentos legales usando la etiqueta <LEGAL_DOC title="..." type="...">Contenido del documento...</LEGAL_DOC>.
`;

/**
 * Mapea el historial de mensajes al formato que requiere Gemini.
 */
const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

/**
 * Función principal para enviar mensajes. 
 * Re-inicializa la sesión para evitar errores de llave expirada o faltante.
 */
export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined") {
    throw new Error("AUTH_REQUIRED");
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = 'gemini-3-flash-preview';

  // Creamos el chat con el historial actual para mantener contexto
  const chat = ai.chats.create({
    model,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.3,
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      if (attachment.isTextExtracted) {
        const augmentedMessage = `${message}\n\n[ARCHIVO: "${attachment.name}"]\n\nCONTENIDO:\n${attachment.content}`;
        result = await chat.sendMessage({ message: augmentedMessage });
      } else {
        const parts: Part[] = [
          { text: message || "Analiza este documento legal." },
          {
            inlineData: {
              mimeType: attachment.type,
              data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
            }
          }
        ];
        result = await chat.sendMessage({ message: parts });
      }
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "Justino está analizando tu solicitud...";

    // Extraer fuentes de Google Search (Grounding)
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Referencia Legal",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Gemini Execution Error:", error);
    if (error.message?.includes("not found") || error.message?.includes("404")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw error;
  }
};

/**
 * Genera un resumen ejecutivo del caso para el historial.
 */
export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

  const ai = new GoogleGenAI({ apiKey });
  const context = messages.slice(-10).map(m => `${m.sender}: ${m.text}`).join('\n');
  const prompt = `Analiza la conversación y resume en JSON: {"antecedents": ["lista strings"], "recommendedActions": ["lista strings"]}. Chat:\n${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: ["Procesando hechos..."], recommendedActions: ["Continuar diálogo."], lastUpdated: new Date() };
  }
};

