import { GoogleGenAI, Chat, GenerateContentResponse, Content, Part } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL DIGITAL MÁS EMPÁTICO Y ESTRATÉGICO DE MÉXICO.

TU OBJETIVO: Llevar al usuario de la mano, con calma y seguridad, resolviendo su caso legal paso a paso.

REGLAS DE ORO DE UX Y COMUNICACIÓN:
1. EMPATÍA PRIMERO: Si el usuario narra una situación difícil (divorcio, despido, maltrato), tu primera frase DEBE ser de apoyo emocional y validación.
2. NO ABRUMES: Prohibido enviar muros de texto o demandas completas en el primer mensaje.
3. MÉTODO SOCRÁTICO: Haz preguntas clave para diagnosticar el caso antes de dar una solución legal. (Ej: "¿Hay hijos?", "¿Existen bienes?", "¿Hay una situación de peligro inmediato?").
4. PASO A PASO: Explica el proceso legal como una escalera. No hables del escalón 10 cuando apenas estamos en el 1.
5. GROUNDING DISCRETO: Usa Google Search para verificar leyes, pero solo cítalas brevemente para dar seguridad, no para dar una clase de derecho.
6. DOCUMENTOS: Solo genera un <LEGAL_DOC> cuando tengas TODOS los datos necesarios (nombres, fechas, detalles) y el usuario te confirme que desea el borrador.

TONO: Mentor, protector, profesional, sereno.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey.length < 10) {
    throw new Error("AUTH_REQUIRED");
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = 'gemini-3-flash-preview';

  const chat = ai.chats.create({
    model,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.4, // Un poco más de calidez
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento y guíame sobre qué hacer." };
      result = await chat.sendMessage({ parts: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "Estoy aquí contigo. ¿Podrías darme más detalles?";
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Referencia Legal",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Gemini Error:", error);
    const msg = error.message?.toLowerCase() || "";
    if (msg.includes("quota") || msg.includes("429") || msg.includes("billing") || msg.includes("403")) {
      throw new Error("BILLING_OR_QUOTA_REQUIRED");
    }
    if (msg.includes("api_key") || msg.includes("invalid") || msg.includes("401")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

  const ai = new GoogleGenAI({ apiKey });
