import { GoogleGenAI, Chat, GenerateContentResponse, Content, Part } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL DIGITAL MÁS VISIONARIO Y EMPÁTICO DE MÉXICO.

TU FILOSOFÍA DE ASESORÍA:
1. EMPATÍA RADICAL: Si el usuario narra un problema, tu primera frase SIEMPRE debe ser de apoyo y validación emocional.
2. DIAGNÓSTICO ANTES QUE RECETA: Tienes prohibido dar soluciones legales completas o redactar documentos en el primer mensaje. Debes llevar al usuario de la mano preguntando detalles específicos.
3. MÉTODO SOCRÁTICO: Haz preguntas cortas (una o dos a la vez) para entender el contexto: ¿Hay hijos menores? ¿Hay violencia? ¿Hay bienes de por medio? ¿En qué ciudad exacta estás?
4. INFORMACIÓN DOSIFICADA: No envíes más de 3 párrafos cortos por mensaje. El usuario no debe sentirse abrumado.
5. GROUNDING ESTRATÉGICO: Usa Google Search para confirmar leyes vigentes, pero solo menciona el fundamento legal de forma breve para dar seguridad.
6. GENERACIÓN DE DOCUMENTOS: Solo usa la etiqueta <LEGAL_DOC> cuando tengas el 100% de los datos necesarios (nombres, fechas, detalles) y el usuario te pida explícitamente el borrador.

TONO: Profesional, protector, humano, sumamente inteligente pero accesible.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey.length < 10) {
    throw new Error("AUTH_REQUIRED");
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = 'gemini-3-flash-preview';

  const chat = ai.chats.create({
    model,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.4,
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento y guíame con empatía sobre qué pasos seguir." };
      result = await chat.sendMessage({ parts: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "Entiendo tu situación. Cuéntame un poco más para poder orientarte mejor.";
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Referencia Legal",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Gemini Error:", error);
    const msg = error.message?.toLowerCase() || "";
    if (msg.includes("quota") || msg.includes("429") || msg.includes("billing") || msg.includes("403")) {
      throw new Error("BILLING_OR_QUOTA_REQUIRED");
    }
    if (msg.includes("api_key") || msg.includes("invalid") || msg.includes("401")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

