import React, { useState, useEffect } from 'react';
import { LandingPage } from './components/LandingPage';
import { OnboardingModal } from './components/OnboardingModal';
import { Dashboard } from './components/Dashboard';
import { LoginModal } from './components/LoginModal';
import { AdminLogin } from './components/AdminLogin';
import { AdminDashboard } from './components/AdminDashboard';
import { User, AppView, Message, VaultFile } from './types';
import { supabase } from './services/supabaseClient';

function App() {
  const [view, setView] = useState<AppView>('landing');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1); // Default step 1

  const [user, setUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [vaultFiles, setVaultFiles] = useState<VaultFile[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);

  // 1. Session & URL Params Check
  useEffect(() => {
    // Check URL parameters (Return from Stripe)
    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');

    if (success === 'true') {
        // Stripe returned success -> Open Onboarding at Step 3 (Account Creation)
        setView('onboarding');
        setOnboardingStep(3);
        // Clean URL
        window.history.replaceState({}, document.title, window.location.pathname);
    } else {
        // Normal Session Check
        const isSessionActive = sessionStorage.getItem('justino_session_active');
        const savedUser = localStorage.getItem('justino_user');

        if (isSessionActive && savedUser) {
          const parsedUser = JSON.parse(savedUser);
          setUser(parsedUser);
          setView('dashboard');
          // We trigger loadMessages inside a separate effect that watches 'user'
        }

        // Admin Check
        const isAdminActive = sessionStorage.getItem('justino_admin_active');
        if (isAdminActive) {
            setView('admin-dashboard');
        }
    }
  }, []);

  // 2. Load Data (Cloud + Local Merge)
  useEffect(() => {
    if (user && view === 'dashboard') {
        // Local Sync
        localStorage.setItem('justino_user', JSON.stringify(user));

        // Cloud Fetch
        const fetchCloudData = async () => {
            if (!supabase || !user.id) {
                // Fallback to local if no cloud ID or no connection
                loadLocalData();
                return;
            }

            setIsSyncing(true);
            try {
                // Fetch Messages
                const { data: msgs, error: msgError } = await supabase
                    .from('messages')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('timestamp', { ascending: true });

                if (msgs && !msgError) {
                    const formattedMessages: Message[] = msgs.map(m => ({
                        id: m.id,
                        text: m.text,
                        sender: m.sender,
                        timestamp: new Date(m.timestamp),
                        attachment: m.attachment || undefined
                    }));

                    // FIX: Race condition protection.
                    // If Cloud returns empty (new user), but we just added the 'welcome' message locally
                    // via ChatInterface, preserve the local state instead of wiping it.
                    setMessages(prev => {
                        if (formattedMessages.length === 0 && prev.some(m => m.id === 'welcome')) {
                            return prev;
                        }
                        return formattedMessages;
                    });

                    // Also update local storage for offline backup
                    if (formattedMessages.length > 0) {
                        localStorage.setItem('justino_messages', JSON.stringify(formattedMessages));
                    }
                }

                // Fetch Files
                const { data: files, error: fileError } = await supabase
                    .from('documents')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('created_at', { ascending: false });

                if (files && !fileError) {
                    const formattedFiles: VaultFile[] = files.map(f => ({
                        id: f.id,
                        name: f.name,
                        type: f.type,
                        content: f.content,
                        origin: f.origin as 'generated' | 'uploaded',
                        date: f.created_at
                    }));
                    setVaultFiles(formattedFiles);
                    localStorage.setItem('justino_vault', JSON.stringify(formattedFiles));
                }

            } catch (e) {
                console.error("Sync Error", e);
                loadLocalData();
            } finally {
                setIsSyncing(false);
            }
        };

        fetchCloudData();
    }
  }, [user, view]);

  const loadLocalData = () => {
    const savedMessages = localStorage.getItem('justino_messages');
    if (savedMessages) {
      const parsed = JSON.parse(savedMessages);
      setMessages(parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })));
    }

    const savedFiles = localStorage.getItem('justino_vault');
    if (savedFiles) {
      setVaultFiles(JSON.parse(savedFiles));
    }
  };

  const handleStart = () => {
    setView('onboarding');
    setOnboardingStep(1);
  };

  const handleLoginClick = () => {
    setShowLoginModal(true);
  };

  const cancelOnboarding = () => {
    setView('landing');
    setOnboardingStep(1);
  };

  const cancelLogin = () => {
    setShowLoginModal(false);
  };

  const handleLoginSuccess = (loggedInUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(loggedInUser);
    setShowLoginModal(false);
    setView('dashboard');
  };

  const completeOnboarding = async (newUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = () => {
    sessionStorage.removeItem('justino_session_active');
    setUser(null);
    setMessages([]);
    setVaultFiles([]);
    setView('landing');
  };

  const handleNewMessage = async (msg: Message) => {
    // 1. Optimistic UI Update
    setMessages(prev => [...prev, msg]);

    // 2. Cloud Save
    if (supabase && user?.id) {
        try {
            await supabase.from('messages').insert([{
                id: msg.id,
                case_id: user.id,
                text: msg.text,
                sender: msg.sender,
                timestamp: msg.timestamp.toISOString(),
                attachment: msg.attachment ? msg.attachment : null
            }]);
        } catch (e) {
            console.error("Failed to save message to cloud", e);
        }
    }

    // 3. Local Backup
    const currentMsgs = [...messages, msg];
    localStorage.setItem('justino_messages', JSON.stringify(currentMsgs));
  };

  const handleAddFile = async (name: string, type: string, content: string, origin: 'generated' | 'uploaded' = 'generated') => {
    const newFile: VaultFile = {
      id: Date.now().toString(),
      name,
      type,
      date: new Date().toISOString(),
      content,
      origin
    };

    // 1. Optimistic UI
    setVaultFiles(prev => [newFile, ...prev]);

    // 2. Cloud Save
    if (supabase && user?.id) {
        try {
            await supabase.from('documents').insert([{
                id: newFile.id,
                case_id: user.id,
                name,
                type,
                content, // Storing base64 text directly in DB for simplicity of this MVP
                origin,
                created_at: newFile.date
            }]);
        } catch (e) {
            console.error("Failed to save file to cloud", e);
        }
    }

    // 3. Local Backup
    const currentFiles = [newFile, ...vaultFiles];
    localStorage.setItem('justino_vault', JSON.stringify(currentFiles));
  };

  // --- ADMIN LOGIC ---
  const handleAdminAccess = () => {
      setView('admin-login');
  };

  const handleAdminLoginSuccess = () => {
      sessionStorage.setItem('justino_admin_active', 'true');
      setView('admin-dashboard');
  };

  const handleAdminLogout = () => {
      sessionStorage.removeItem('justino_admin_active');
      setView('landing');
  };

  const hasExistingSession = !!localStorage.getItem('justino_user');

  return (
    <>
      {view === 'landing' && (
        <LandingPage 
            onStart={handleStart} 
            onLogin={handleLoginClick}
            onAdminAccess={handleAdminAccess} 
            hasExistingSession={hasExistingSession} 
        />
      )}

      {showLoginModal && (
        <LoginModal onSuccess={handleLoginSuccess} onClose={cancelLogin} />
      )}

      {view === 'onboarding' && (
        <>
          <LandingPage onStart={() => {}} onLogin={() => {}} onAdminAccess={() => {}} hasExistingSession={hasExistingSession} /> 
          <OnboardingModal 
            onComplete={completeOnboarding} 
            onClose={cancelOnboarding} 
            initialStep={onboardingStep}
          />
        </>
      )}

      {view === 'dashboard' && user && (
        <Dashboard 
          user={user} 
          messages={messages} 
          vaultFiles={vaultFiles}
          onNewMessage={handleNewMessage}
          onAddFile={handleAddFile}
          onLogout={handleLogout}
        />
      )}

      {/* Admin Views */}
      {view === 'admin-login' && (
          <AdminLogin onSuccess={handleAdminLoginSuccess} onClose={() => setView('landing')} />
      )}

      {view === 'admin-dashboard' && (
          <AdminDashboard onLogout={handleAdminLogout} />
      )}
    </>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User, Message, Attachment } from '../types';
import { sendMessageToJustino } from '../services/geminiService';
import { Send as SendIcon, Paperclip as PaperclipIcon, Scale as ScaleIcon, ExternalLink as ExternalLinkIcon, Globe as GlobeIcon, Loader2 as Loader2Icon, ShieldCheck as ShieldCheckIcon, AlertCircle as AlertCircleIcon } from 'lucide-react';

interface CustomWindow extends Window {
  aistudio: any;
}
declare const window: CustomWindow;

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

const LOADING_MESSAGES = [
  "Analizando tu situación...",
  "Obteniendo información legal...",
  "Procesando estrategia ganadora...",
  "Revisando todos los ángulos...",
  "Fundamentando con leyes vigentes...",
  "Preparando el siguiente paso táctico..."
];

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);
  const [attachment, setAttachment] = useState<Attachment | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Bienvenida Oficial
  useEffect(() => {
    if (messages.length === 0) {
      onNewMessage({
        id: 'welcome',
        text: `Hola soy Justino tu asistente legal digital, Mi objetivo es asesorarte en cualquier situación legal que necesites y ofrecerte las mejores opciones, de forma realista y siempre basado en la legislación vigente.\n\nEstás en un espacio 100% seguro. Tu información es confidencial y está codificada, Nadie puede acceder a ella.\n\nPara poder ayudarte de la mejor forma dime ¿En que ciudad te encuentras y que asunto legal vamos a resolver?`,
        sender: 'bot',
        timestamp: new Date(),
      });
    }
  }, []);

  // Rotador de mensajes de carga
  useEffect(() => {
    let interval: any;
    if (isSending) {
      interval = setInterval(() => {
        setLoadingMsgIdx((prev) => (prev + 1) % LOADING_MESSAGES.length);
      }, 2000);
    } else {
      setLoadingMsgIdx(0);
    }
    return () => clearInterval(interval);
  }, [isSending]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isSending]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentInput = input;
    const currentAttachment = attachment;

    setInput('');
    setAttachment(null);
    setIsSending(true);

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput || (currentAttachment ? `Analizando archivo: ${currentAttachment.name}` : ""),
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };
    onNewMessage(userMsg);

    try {
      const response = await sendMessageToJustino(currentInput, messages, currentAttachment || undefined);

      onNewMessage({
        id: (Date.now() + 1).toString(),
        text: response.text,
        sender: 'bot',
        timestamp: new Date(),
        sources: response.sources.length > 0 ? response.sources : undefined
      });
    } catch (error: any) {
      console.error("ChatInterface Error:", error);

      if (error.message === "AUTH_REQUIRED" || error.message === "BILLING_OR_QUOTA_REQUIRED") {
        const isBilling = error.message === "BILLING_OR_QUOTA_REQUIRED";

        onNewMessage({
          id: 'auth-error',
          text: isBilling 
            ? "Tu cuenta de IA requiere activar la facturación en Google Cloud para acceder a las leyes más recientes."
            : "Para que pueda asesorarte adecuadamente, necesito que vincules una cuenta de Google Gemini activa.",
          sender: 'bot',
          timestamp: new Date()
        });

        if (window.aistudio) {
          await window.aistudio.openSelectKey();
        }
      } else {
        onNewMessage({ 
          id: 'error', 
          text: "Hubo un error en el protocolo. Por favor, reintenta.", 
          sender: 'bot', 
          timestamp: new Date() 
        });
      }
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F8FAFC] relative">
      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
            <div className={`max-w-[85%] md:max-w-[70%] px-6 py-5 rounded-3xl shadow-sm text-[15px] leading-relaxed ${
              msg.sender === 'user' 
                ? 'bg-navy-900 text-white rounded-tr-none' 
                : msg.id.includes('error')
                  ? 'bg-red-50 text-red-800 rounded-tl-none border border-red-100'
                  : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'
            }`}>
              <div className="space-y-4">
                <div className="flex items-start gap-3">
                  {msg.id.includes('error') && <AlertCircleIcon className="w-5 h-5 mt-1 shrink-0" />}
                  <div className="whitespace-pre-wrap">{msg.text}</div>
                </div>

                {msg.sources && (
                  <div className="mt-4 pt-4 border-t border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                      <GlobeIcon className="w-3 h-3 text-emerald-500" /> Referencias Legales Verificadas
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((s, i) => (
                        <a key={i} href={s.uri} target="_blank" rel="noopener" className="inline-flex items-center gap-2 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-bold text-navy-900 hover:bg-emerald-50 transition-all">
                          <ExternalLinkIcon className="w-3 h-3 text-emerald-600" /> <span className="truncate max-w-[140px]">{s.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-6 py-5 rounded-3xl rounded-tl-none shadow-xl flex items-center gap-5 border-l-4 border-emerald-500">
               <div className="relative">
                  <ScaleIcon className="w-8 h-8 text-emerald-500 animate-pulse" />
                  <Loader2Icon className="w-8 h-8 text-emerald-500/20 animate-spin absolute inset-0" />
               </div>
               <div className="flex flex-col">
                 <span className="text-sm font-black text-navy-900 tracking-tight uppercase">Justino está analizando</span>
                 <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-[0.2em] animate-pulse">
                   {LOADING_MESSAGES[loadingMsgIdx]}
                 </span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="bg-white border-t border-slate-100 p-4 md:p-6 z-20">
        <div className="max-w-4xl mx-auto flex items-end gap-4">
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = (re) => setAttachment({ name: file.name, type: file.type, content: re.target?.result as string, isTextExtracted: !file.type.includes('pdf') && !file.type.includes('image') });
              reader.readAsDataURL(file);
            }
          }} />
          <button type="button" onClick={() => fileInputRef.current?.click()} className={`p-4 rounded-2xl transition-all ${attachment ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>
            <PaperclipIcon className="w-6 h-6" />
          </button>
          <form onSubmit={handleSend} className="flex-1 flex items-end gap-3">
            <div className="flex-1 bg-slate-50 rounded-2xl border border-slate-200 focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner relative">
              {attachment && (
                <div className="absolute -top-12 left-0 right-0 p-2">
                   <div className="bg-emerald-500 text-white text-[10px] font-bold px-3 py-1 rounded-full flex items-center justify-between shadow-lg">
                      <span className="truncate max-w-[200px]">Adjunto: {attachment.name}</span>
                      <button type="button" onClick={() => setAttachment(null)} className="ml-2">✕</button>
                   </div>
                </div>
              )}
              <textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                placeholder="Cuéntame tu caso, te escucho..."
                className="w-full max-h-40 p-5 resize-none bg-transparent focus:outline-none text-navy-900 font-medium"
                rows={1}
              />
            </div>
            <button type="submit" disabled={(!input.trim() && !attachment) || isSending} className="p-5 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:opacity-30 transition-all shadow-xl active:scale-95">
              <SendIcon className="w-6 h-6" />
            </button>
          </form>
        </div>
        <div className="mt-4 flex items-center justify-center gap-2 text-[9px] font-bold text-slate-400 uppercase tracking-[0.3em]">
           <ShieldCheckIcon className="w-3 h-3 text-emerald-500" /> Bóveda de Datos Privada
        </div>
      </div>
    </div>
  );
}

