                  <span className="text-3xl font-black text-emerald-700 leading-none">$400</span>
                  <p className="text-[10px] text-emerald-600 font-bold">MXN</p>
                </div>
              </div>

              {/* Stripe Payment Button */}
              <div className="space-y-3">
                <button 
